def initiate_login(user_id, state=None, **_extra):
    import json, os, datetime, re, secrets, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Load
    users = _load("users.json")
    sessions = _load("auth_sessions.json")

    # Validate
    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[A-Za-z0-9]+$", user_id):
        return _err("VALIDATION_ERROR", "Invalid user_id format.", field="user_id")
    if state is not None and not isinstance(state, str):
        return _err("VALIDATION_ERROR", "state must be a string when provided.", field="state")
    if state is not None and len(state) == 0:
        return _err("VALIDATION_ERROR", "state must not be empty when provided.", field="state")

    user = next((u for u in users if u.get("id") == user_id), None)
    if not user:
        return _err("NOT_FOUND", "User not found.", user_id=user_id)
    if user.get("status") != "active":
        return _err("UNAUTHORIZED", "User is not active.", user_id=user_id, user_status=user.get("status"))

    # Enforce CONFLICT if in-progress login attempt exists for user (not completed/expired)
    in_progress_statuses = {"login_initiated", "request_token_received"}
    for s in sessions:
        if s.get("user_id") == user_id and s.get("status") in in_progress_statuses:
            return _err(
                "CONFLICT",
                "There is already an in-progress login attempt for this user.",
                user_id=user_id,
                auth_session_id=s.get("id"),
                status=s.get("status"),
            )

    # Generate unique state if not provided; also ensure uniqueness across sessions (unique(state))
    existing_states = {s.get("state") for s in sessions if s.get("state")}
    if state is None:
        # ensure reasonably unique and not too long
        for _ in range(50):
            candidate = "st_" + secrets.token_urlsafe(16).replace("-", "").replace("_", "")
            if candidate not in existing_states:
                state = candidate
                break
        else:
            return _err("CONFLICT", "Could not allocate a unique state; try again.")
    else:
        if state in existing_states:
            return _err("CONFLICT", "state is already in use by another session.", field="state")

    # Create new session with status=login_initiated
    # id convention: zui_sess_<alnum>
    existing_ids = {s.get("id") for s in sessions if isinstance(s.get("id"), str)}
    for _ in range(50):
        new_id = "zui_sess_" + secrets.token_hex(8)
        if new_id not in existing_ids:
            auth_session_id = new_id
            break
    else:
        return _err("CONFLICT", "Could not allocate a unique auth_session_id; try again.")

    # Construct a plausible login_url that binds state (offline service)
    login_url = "https://kite.zerodha.com/connect/login?state=" + state

    new_row = {
        "id": auth_session_id,
        "user_id": user_id,
        "state": state,
        "login_url": login_url,
        "redirected_at": None,
        "request_token": None,
        "request_token_expires_at": None,
        "access_token": None,
        "access_token_expires_at": None,
        "kite_user_id": None,
        "status": "login_initiated",
        "last_error_code": None,
        "last_error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    sessions.append(new_row)
    _save("auth_sessions.json", sessions)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "auth_session": {
            "id": auth_session_id,
            "user_id": user_id,
            "state": state,
            "login_url": login_url,
            "status": "login_initiated",
            "created_at": now_iso,
            "updated_at": now_iso,
        },
        "meta": {"latency_ms": latency_ms},
    }

def get_request_token(auth_session_id, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_request_token"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(st)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _audit(status, credential=None, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now_dt()),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(auth_session_id, str) or not re.match(r"^zui_sess_[A-Za-z0-9]+$", auth_session_id):
        e = _err("VALIDATION_ERROR", "auth_session_id is malformed", field="auth_session_id")
        _audit("error", auth_session_id, e["error"])
        return e

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == auth_session_id), None)
    if sess is None:
        e = _err("NOT_FOUND", "Auth session not found", auth_session_id=auth_session_id)
        _audit("error", auth_session_id, e["error"])
        return e

    st = sess.get("status")
    # Realistic behaviour: if authenticated, request_token may have been cleared/expired; don't error, just return what is known.
    # Only refuse when session is clearly not in a readable phase (created/failed/etc.) and has no request_token recorded.
    token = sess.get("request_token")
    exp = sess.get("request_token_expires_at")

    # If token exists but expired, transition to expired when allowed (login_initiated/request_token_received/authenticated -> expired)
    exp_dt = _parse_dt(exp)
    now = _now_dt()
    if token and exp_dt is not None and exp_dt <= now:
        # try transition to expired if legal from current status
        transitions = {
            "created": ["login_initiated", "failed"],
            "login_initiated": ["request_token_received", "failed", "expired"],
            "request_token_received": ["authenticated", "failed", "expired"],
            "authenticated": ["expired", "revoked", "failed"],
            "expired": ["login_initiated"],
            "revoked": ["login_initiated"],
            "failed": ["login_initiated"],
        }
        if st in transitions and "expired" in transitions.get(st, []):
            sess["status"] = "expired"
            sess["updated_at"] = _iso(now)
            st = "expired"
            _save("auth_sessions.json", sessions)

    # If in the canonical readable states, return token (may be null if redirect not completed).
    if st in ("login_initiated", "request_token_received"):
        resp = {
            "auth_session_id": auth_session_id,
            "status": st,
            "request_token": token,
            "request_token_expires_at": exp,
            "redirected_at": sess.get("redirected_at"),
            "updated_at": sess.get("updated_at"),
        }
        _audit("ok", auth_session_id, meta={"returned": True, "status": st, "has_request_token": bool(token)})
        return resp

    # For authenticated/expired/revoked/failed: return token if present; otherwise conflict (nothing to read).
    if token:
        resp = {
            "auth_session_id": auth_session_id,
            "status": st,
            "request_token": token,
            "request_token_expires_at": exp,
            "redirected_at": sess.get("redirected_at"),
            "updated_at": sess.get("updated_at"),
        }
        _audit("ok", auth_session_id, meta={"returned": True, "status": st, "has_request_token": True})
        return resp

    e = _err(
        "CONFLICT",
        "Session does not have a readable request_token (redirect not completed or already exchanged/cleared).",
        auth_session_id=auth_session_id,
        status=st,
    )
    _audit("error", auth_session_id, e["error"])
    return e

def get_holdings(user_id, auth_session_id=None, refresh=None, **_extra):
    import json, os, datetime, re, secrets, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Validate
    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[A-Za-z0-9]+$", user_id):
        return _err("VALIDATION_ERROR", "Invalid user_id format.", field="user_id")
    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided.", field="refresh")
    if refresh:
        if auth_session_id is None:
            return _err("VALIDATION_ERROR", "auth_session_id is required when refresh=true.", field="auth_session_id")
        if not isinstance(auth_session_id, str) or not re.match(r"^zui_sess_[A-Za-z0-9]+$", auth_session_id):
            return _err("VALIDATION_ERROR", "Invalid auth_session_id format.", field="auth_session_id")

    users = _load("users.json")
    sessions = _load("auth_sessions.json")
    snaps = _load("portfolio_snapshots.json")

    user = next((u for u in users if u.get("id") == user_id), None)
    if not user:
        return _err("NOT_FOUND", "User not found.", user_id=user_id)
    if user.get("status") != "active":
        return _err("UNAUTHORIZED", "User is not active.", user_id=user_id, user_status=user.get("status"))

    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            s2 = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    # If refresh requested, require authenticated session with non-expired token
    created_snapshot = None
    if refresh:
        sess = next((s for s in sessions if s.get("id") == auth_session_id), None)
        if not sess:
            # Must create/login_initiated a new session and report not authenticated (rule)
            return _err(
                "UNAUTHORIZED",
                "Auth session not found; not authenticated. Initiate login.",
                user_id=user_id,
                auth_session_id=auth_session_id,
                auth_required=True,
            )
        if sess.get("user_id") != user_id:
            return _err("UNAUTHORIZED", "Auth session does not belong to the user.", user_id=user_id, auth_session_id=auth_session_id)

        exp_dt = _parse_dt(sess.get("access_token_expires_at"))
        if sess.get("status") != "authenticated" or exp_dt is None or exp_dt <= now:
            # Not authenticated per rules
            return _err(
                "UNAUTHORIZED",
                "Session is not authenticated or access token expired; initiate login.",
                user_id=user_id,
                auth_session_id=auth_session_id,
                session_status=sess.get("status"),
                auth_required=True,
            )

        # Simulate upstream fetch (offline): succeed with an empty structure but real persistence side-effects.
        # Create portfolio_snapshots row per call
        existing_ids = {s.get("id") for s in snaps if isinstance(s.get("id"), str)}
        for _ in range(50):
            snap_id = "zui_snap_" + secrets.token_hex(8)
            if snap_id not in existing_ids:
                break
        else:
            return _err("CONFLICT", "Could not allocate snapshot id; try again.")

        payload = {"holdings": [], "fetched_at": now_iso, "note": "offline_stub_no_upstream"}
        created_snapshot = {
            "id": snap_id,
            "user_id": user_id,
            "auth_session_id": auth_session_id,
            "snapshot_type": "holdings",
            "as_of": now_iso,
            "status": "fresh",
            "payload": payload,
            "source": "kite_api",
            "created_at": now_iso,
            "updated_at": now_iso,
        }

        # unique(user_id, snapshot_type, as_of)
        for s in snaps:
            if s.get("user_id") == user_id and s.get("snapshot_type") == "holdings" and s.get("as_of") == now_iso:
                return _err("CONFLICT", "A holdings snapshot already exists for this as_of.", user_id=user_id, as_of=now_iso)

        snaps.append(created_snapshot)
        _save("portfolio_snapshots.json", snaps)

    # Return latest persisted holdings snapshot for user
    candidates = [s for s in snaps if s.get("user_id") == user_id and s.get("snapshot_type") == "holdings"]
    candidates.sort(key=lambda r: (_parse_dt(r.get("as_of")) or datetime.datetime.min), reverse=True)
    latest = candidates[0] if candidates else None

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "user_id": user_id,
        "snapshot": latest,
        "refreshed": bool(refresh),
        "created_snapshot": created_snapshot["id"] if created_snapshot else None,
        "meta": {"latency_ms": latency_ms},
    }

