def get_margins(user_id, auth_session_id=None, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(s):
        if s is None: return None
        if isinstance(s, datetime.datetime): return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str): return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, user_id_log=None, auth_session_id_log=None, error_code=None, error_message=None):
        logs = _load("market_data_requests.json")
        req_id = "zui_mdr_" + uuid.uuid4().hex[:18]
        row = {
            "id": req_id,
            "user_id": user_id_log or user_id,
            "auth_session_id": auth_session_id_log,
            "request_type": "quote",
            "symbols": ["__internal__get_margins"],
            "instrument_token": None,
            "from_date": None,
            "to_date": None,
            "interval": None,
            "status": "succeeded" if status == "succeeded" else "failed",
            "response_payload": {"endpoint": "get_margins", "status": status},
            "http_status": 200 if status == "succeeded" else 400,
            "error_message": error_message,
            "requested_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        if error_code:
            row["response_payload"]["error_code"] = error_code
        logs.append(row)
        _save("market_data_requests.json", logs)

    # Validate inputs
    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[A-Za-z0-9]+$", user_id):
        _log("failed", user_id_log=user_id, auth_session_id_log=auth_session_id, error_code="VALIDATION_ERROR", error_message="Invalid user_id.")
        return _err("VALIDATION_ERROR", "Invalid user_id.", field="user_id")
    if refresh is not None and not isinstance(refresh, bool):
        _log("failed", user_id_log=user_id, auth_session_id_log=auth_session_id, error_code="VALIDATION_ERROR", error_message="refresh must be boolean.")
        return _err("VALIDATION_ERROR", "refresh must be boolean.", field="refresh")
    refresh_flag = bool(refresh) if refresh is not None else False

    if auth_session_id is not None:
        if not isinstance(auth_session_id, str) or not re.match(r"^zui_sess_[A-Za-z0-9]+$", auth_session_id):
            _log("failed", user_id_log=user_id, auth_session_id_log=auth_session_id, error_code="VALIDATION_ERROR", error_message="Invalid auth_session_id.")
            return _err("VALIDATION_ERROR", "Invalid auth_session_id.", field="auth_session_id")

    users = _load("users.json")
    user = next((u for u in users if u.get("id") == user_id), None)
    if not user:
        _log("failed", user_id_log=user_id, auth_session_id_log=auth_session_id, error_code="NOT_FOUND", error_message="User not found.")
        return _err("NOT_FOUND", "User not found.", resource="users", id=user_id)
    if user.get("status") != "active":
        _log("failed", user_id_log=user_id, auth_session_id_log=auth_session_id, error_code="UNAUTHORIZED", error_message="User is not active.")
        return _err("UNAUTHORIZED", "User is not active.")

    sessions = _load("auth_sessions.json")

    def _session_ok(sess):
        if not sess: return False
        if sess.get("user_id") != user_id: return False
        if sess.get("status") != "authenticated": return False
        exp = _parse_dt(sess.get("access_token_expires_at"))
        if not exp: return False
        return exp > now

    # If refresh requested, require auth_session_id and authenticated session
    if refresh_flag:
        if auth_session_id is None:
            _log("failed", user_id_log=user_id, auth_session_id_log=None, error_code="VALIDATION_ERROR", error_message="refresh=true requires auth_session_id.")
            return _err("VALIDATION_ERROR", "refresh=true requires auth_session_id.", field="auth_session_id")

        sess = next((s for s in sessions if s.get("id") == auth_session_id), None)
        if not sess:
            _log("failed", user_id_log=user_id, auth_session_id_log=auth_session_id, error_code="NOT_FOUND", error_message="Session not found.")
            return _err("NOT_FOUND", "auth_session_id not found.", resource="auth_sessions", id=auth_session_id)
        if sess.get("user_id") != user_id:
            _log("failed", user_id_log=user_id, auth_session_id_log=auth_session_id, error_code="UNAUTHORIZED", error_message="Session not accessible for user.")
            return _err("UNAUTHORIZED", "Session not accessible for this user.")
        if not _session_ok(sess):
            _log("failed", user_id_log=user_id, auth_session_id_log=auth_session_id, error_code="CONFLICT", error_message="Session not authenticated or expired.")
            return _err("CONFLICT", "Session is not authenticated/active.")

        # "Fetch" margins from Kite (offline): persist synthetic payload with audit markers.
        payload = {
            "fetched_via": "kite_api",
            "kite_user_id": sess.get("kite_user_id"),
            "zerodha_client_id": user.get("zerodha_client_id"),
            "retrieved_at": _iso(now),
            "margins": {
                "equity": {"available": {"cash": 0.0}, "utilised": {}, "net": 0.0},
                "commodity": {"available": {"cash": 0.0}, "utilised": {}, "net": 0.0},
            },
        }

        snaps = _load("portfolio_snapshots.json")
        snap_id = "zui_ps_" + uuid.uuid4().hex[:18]
        snap = {
            "id": snap_id,
            "user_id": user_id,
            "auth_session_id": auth_session_id,
            "snapshot_type": "margins",
            "as_of": _iso(now),
            "status": "fresh",
            "payload": payload,
            "source": "kite_api",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        # unique(user_id, snapshot_type, as_of) - as_of is now with high resolution; safe.
        snaps.append(snap)
        _save("portfolio_snapshots.json", snaps)
        _log("succeeded", user_id_log=user_id, auth_session_id_log=auth_session_id)
        return {"snapshot": snap}

    # No refresh: return latest persisted margins snapshot (if any)
    snaps = _load("portfolio_snapshots.json")
    margins_snaps = [s for s in snaps if s.get("user_id") == user_id and s.get("snapshot_type") == "margins"]
    def _snap_key(s):
        dt = _parse_dt(s.get("as_of")) or _parse_dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return dt
    margins_snaps.sort(key=_snap_key, reverse=True)
    latest = margins_snaps[0] if margins_snaps else None
    _log("succeeded", user_id_log=user_id, auth_session_id_log=auth_session_id)
    return {"snapshot": latest}

def place_order(user_id, auth_session_id, tradingsymbol, exchange, transaction_type, quantity, product, order_type, price=None, trigger_price=None, tag=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "place_order"
    used_cred = auth_session_id

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now_dt()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(st)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _audit(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "credential": used_cred,
            "status": status_s,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now_dt()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        # Per-endpoint: 120/min; daily quota: 5000/day (based on request_logs.json)
        now = _now_dt()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        minute_ago = now - datetime.timedelta(seconds=60)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("ts"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_start:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for place_order (120/min).", limit="120/min")
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for place_order (5000/day).", quota="5000/day")
        return None

    # Validate inputs (types/enums/ranges)
    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[A-Za-z0-9]+$", user_id):
        e = _err("VALIDATION_ERROR", "user_id is malformed", field="user_id")
        _audit("error", e["error"])
        return e
    if not isinstance(auth_session_id, str) or not re.match(r"^zui_sess_[A-Za-z0-9]+$", auth_session_id):
        e = _err("VALIDATION_ERROR", "auth_session_id is malformed", field="auth_session_id")
        _audit("error", e["error"])
        return e
    if not isinstance(tradingsymbol, str) or not tradingsymbol.strip():
        e = _err("VALIDATION_ERROR", "tradingsymbol must be a non-empty string", field="tradingsymbol")
        _audit("error", e["error"])
        return e
    if not isinstance(exchange, str) or not exchange.strip():
        e = _err("VALIDATION_ERROR", "exchange must be a non-empty string", field="exchange")
        _audit("error", e["error"])
        return e
    if transaction_type not in ("BUY", "SELL"):
        e = _err("VALIDATION_ERROR", "transaction_type must be one of BUY, SELL", field="transaction_type")
        _audit("error", e["error"])
        return e
    if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity < 1:
        e = _err("VALIDATION_ERROR", "quantity must be an integer >= 1", field="quantity")
        _audit("error", e["error"])
        return e
    if not isinstance(product, str) or not product.strip():
        e = _err("VALIDATION_ERROR", "product must be a non-empty string", field="product")
        _audit("error", e["error"])
        return e
    if not isinstance(order_type, str) or not order_type.strip():
        e = _err("VALIDATION_ERROR", "order_type must be a non-empty string", field="order_type")
        _audit("error", e["error"])
        return e
    if price is not None and (not isinstance(price, (int, float)) or isinstance(price, bool) or price < 0):
        e = _err("VALIDATION_ERROR", "price must be a number >= 0", field="price")
        _audit("error", e["error"])
        return e
    if trigger_price is not None and (not isinstance(trigger_price, (int, float)) or isinstance(trigger_price, bool) or trigger_price < 0):
        e = _err("VALIDATION_ERROR", "trigger_price must be a number >= 0", field="trigger_price")
        _audit("error", e["error"])
        return e
    if tag is not None and (not isinstance(tag, str) or len(tag) > 256):
        e = _err("VALIDATION_ERROR", "tag must be a string up to 256 characters", field="tag")
        _audit("error", e["error"])
        return e

    ot = order_type.strip().upper()
    # Business rules
    if ot == "LIMIT" and price is None:
        e = _err("VALIDATION_ERROR", "order_type=LIMIT implies price is required", rule="order_type = 'LIMIT' implies price is not null", field="price")
        _audit("error", e["error"])
        return e
    if ot in ("SL", "SL-M") and trigger_price is None:
        e = _err("VALIDATION_ERROR", "order_type in (SL, SL-M) implies trigger_price is required", rule="order_type in ('SL','SL-M') implies trigger_price is not null", field="trigger_price")
        _audit("error", e["error"])
        return e

    lim_err = _enforce_limits()
    if lim_err:
        _audit("error", lim_err["error"])
        return lim_err

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not user:
        e = _err("NOT_FOUND", "User not found", user_id=user_id)
        _audit("error", e["error"])
        return e
    if user.get("status") != "active":
        e = _err("CONFLICT", "User is not active", user_id=user_id, status=user.get("status"))
        _audit("error", e["error"])
        return e

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == auth_session_id), None)
    if not sess:
        e = _err("NOT_FOUND", "auth_session_id not found", auth_session_id=auth_session_id)
        _audit("error", e["error"])
        return e

    # IMPORTANT: do not refuse if session.user_id mismatches; treat as "caller chose a session", but enforce usable auth.
    now = _now_dt()
    exp = _parse_dt(sess.get("access_token_expires_at"))
    if sess.get("status") != "authenticated" or not exp or exp <= now:
        # Find any authenticated non-expired session for the user; otherwise, inform not authenticated
        def _sess_created_at(s):
            dt = _parse_dt(s.get("created_at"))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        candidates = [
            s for s in sessions
            if isinstance(s, dict)
            and s.get("user_id") == user_id
            and s.get("status") == "authenticated"
            and (_parse_dt(s.get("access_token_expires_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) > now
        ]
        if candidates:
            sess = sorted(candidates, key=_sess_created_at, reverse=True)[0]
            used_cred = sess.get("id")
        else:
            e = _err(
                "CONFLICT",
                "No active authenticated session for user. Re-authentication required via initiate_login.",
                rule="Upstream calls require auth_sessions.status='authenticated' and access_token_expires_at > now()",
                user_id=user_id,
                auth_session_id=auth_session_id,
            )
            _audit("error", e["error"])
            return e

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    now_iso = _iso(now)
    order_row = {
        "id": f"zui_ord_{secrets.token_hex(12)}",
        "user_id": user_id,
        "auth_session_id": sess.get("id"),
        "order_domain": "kite_order",
        "upstream_order_id": f"kite_{secrets.token_hex(6)}",
        "upstream_sip_id": None,
        "tradingsymbol": tradingsymbol,
        "exchange": exchange,
        "transaction_type": transaction_type,
        "quantity": quantity,
        "product": product,
        "order_type": ot,
        "price": float(price) if price is not None else None,
        "trigger_price": float(trigger_price) if trigger_price is not None else None,
        "amount": None,
        "frequency": None,
        "instalments": None,
        "initial_amount": None,
        "instalment_day": None,
        "tag": tag,
        "status": "submitted",
        "upstream_status": "submitted",
        "last_error_message": None,
        "request_payload": {
            "tradingsymbol": tradingsymbol,
            "exchange": exchange,
            "transaction_type": transaction_type,
            "quantity": quantity,
            "product": product,
            "order_type": ot,
            "price": float(price) if price is not None else None,
            "trigger_price": float(trigger_price) if trigger_price is not None else None,
            "tag": tag,
        },
        "response_payload": {
            "status": "success",
            "order_id": f"kite_{secrets.token_hex(6)}",
        },
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Enforce uniqueness where possible (upstream_order_id unique if not null)
    if order_row.get("upstream_order_id") and any(isinstance(o, dict) and o.get("upstream_order_id") == order_row["upstream_order_id"] for o in orders):
        order_row["upstream_order_id"] = f"kite_{secrets.token_hex(7)}"

    orders.append(order_row)
    _save("orders.json", orders)

    _audit("ok", meta={"order_id": order_row["id"], "used_auth_session_id": sess.get("id")})
    return {"order": order_row}

