        reqs = []
    now_iso = _iso(now)
    req_row = {
        "id": f"zui_mdr_{secrets.token_hex(12)}",
        "user_id": user_id,
        "auth_session_id": sess.get("id"),
        "request_type": "quote",
        "symbols": list(symbols),
