        "to_date": None,
        "interval": None,
        "status": "succeeded",
        "response_payload": None,
        "http_status": 200,
        "error_message": None,
        "requested_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Offline deterministic-ish quote payload
    data = {}
    base = int(now.timestamp())
    for i, sym in enumerate(symbols):
        # allow any symbol string; do not enforce NSE: prefix
        last = round(((base % 10000) / 10.0) + (i * 3.17) + random.random(), 2)
        o = round(last * (1 - 0.01), 2)
        h = round(last * (1 + 0.02), 2)
        l = round(last * (1 - 0.02), 2)
        c = round(last * (1 - 0.005), 2)
        data[sym] = {
            "instrument_token": None,
            "last_price": last,
            "ohlc": {"open": o, "high": h, "low": l, "close": c},
            "volume": int((base + i * 97) % 100000),
            "timestamp": now_iso,
        }

    req_row["response_payload"] = {"data": data}
    reqs.append(req_row)
    _save("market_data_requests.json", reqs)

    _audit("ok", meta={"market_data_request_id": req_row["id"], "used_auth_session_id": sess.get("id"), "symbols_count": len(symbols)})
    return {"data": data, "market_data_request": req_row}

