            dt = _now_dt()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(st)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _parse_date(d):
        if not isinstance(d, str):
            return None
        try:
            return datetime.date.fromisoformat(d)
        except ValueError:
            return None

    def _audit(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "credential": used_cred,
            "status": status_s,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now_dt()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        # Per-endpoint: 120/minute, daily quota: 5000/day
        now = _now_dt()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        minute_ago = now - datetime.timedelta(seconds=60)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("ts"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_start:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for get_historical_data (120/min).", limit="120/min")
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for get_historical_data (5000/day).", quota="5000/day")
        return None

    # Validate
    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[A-Za-z0-9]+$", user_id):
        e = _err("VALIDATION_ERROR", "user_id is malformed", field="user_id")
        _audit("error", e["error"])
        return e
    if not isinstance(auth_session_id, str) or not re.match(r"^zui_sess_[A-Za-z0-9]+$", auth_session_id):
        e = _err("VALIDATION_ERROR", "auth_session_id is malformed", field="auth_session_id")
        _audit("error", e["error"])
        return e
    if not isinstance(instrument_token, int) or isinstance(instrument_token, bool) or instrument_token <= 0:
        e = _err("VALIDATION_ERROR", "instrument_token must be an integer > 0", field="instrument_token")
        _audit("error", e["error"])
        return e
    fd = _parse_date(from_date)
    td = _parse_date(to_date)
    if not fd:
        e = _err("VALIDATION_ERROR", "from_date must be YYYY-MM-DD", field="from_date")
        _audit("error", e["error"])
        return e
    if not td:
        e = _err("VALIDATION_ERROR", "to_date must be YYYY-MM-DD", field="to_date")
        _audit("error", e["error"])
        return e
    if fd > td:
        e = _err("VALIDATION_ERROR", "from_date must be on or before to_date", field="from_date", from_date=from_date, to_date=to_date)
        _audit("error", e["error"])
        return e
    if not isinstance(interval, str) or not interval.strip():
        e = _err("VALIDATION_ERROR", "interval must be a non-empty string", field="interval")
        _audit("error", e["error"])
        return e

    lim_err = _enforce_limits()
    if lim_err:
        _audit("error", lim_err["error"])
        return lim_err

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not user:
        e = _err("NOT_FOUND", "User not found", user_id=user_id)
        _audit("error", e["error"])
        return e
    if user.get("status") != "active":
        e = _err("CONFLICT", "User is not active", user_id=user_id, status=user.get("status"))
        _audit("error", e["error"])
        return e

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == auth_session_id), None)
    if not sess:
        e = _err("NOT_FOUND", "auth_session_id not found", auth_session_id=auth_session_id)
        _audit("error", e["error"])
        return e

    now = _now_dt()
    exp = _parse_dt(sess.get("access_token_expires_at"))
    if sess.get("status") != "authenticated" or not exp or exp <= now:
        def _sess_created_at(s):
            dt = _parse_dt(s.get("created_at"))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        candidates = [
            s for s in sessions
            if isinstance(s, dict)
            and s.get("user_id") == user_id
            and s.get("status") == "authenticated"
            and (_parse_dt(s.get("access_token_expires_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) > now
        ]
        if candidates:
            sess = sorted(candidates, key=_sess_created_at, reverse=True)[0]
            used_cred = sess.get("id")
        else:
            e = _err(
                "CONFLICT",
                "No active authenticated session for user. Re-authentication required via initiate_login.",
                rule="Upstream calls require auth_sessions.status='authenticated' and access_token_expires_at > now()",
                user_id=user_id,
                auth_session_id=auth_session_id,
            )
            _audit("error", e["error"])
            return e

    # Persist market_data_requests row
    reqs = _load("market_data_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    now_iso = _iso(now)
    req_row = {
        "id": f"zui_mdr_{secrets.token_hex(12)}",
        "user_id": user_id,
        "auth_session_id": sess.get("id"),
        "request_type": "historical",
        "symbols": None,
        "instrument_token": instrument_token,
        "from_date": from_date,
        "to_date": to_date,
        "interval": interval,
        "status": "succeeded",
        "response_payload": None,
        "http_status": 200,
        "error_message": None,
        "requested_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Generate candle series (simple synthetic candles)
    days = (td - fd).days + 1
    max_points = 2000
    n = min(days, max_points)
    seed = (instrument_token * 1103515245 + int(fd.strftime("%Y%m%d"))) & 0x7fffffff
    rnd = random.Random(seed)

    candles = []
    base_price = 100 + (instrument_token % 500) + (seed % 37)
    cur = float(base_price)
    for i in range(n):
        drift = (rnd.random() - 0.5) * 2.0
        open_p = cur
        high_p = open_p + abs(drift) * (1.5 + rnd.random())
        low_p = open_p - abs(drift) * (1.5 + rnd.random())
        close_p = open_p + drift
        vol = int(1000 + rnd.random() * 50000)
        day = fd + datetime.timedelta(days=i)
        ts = datetime.datetime(day.year, day.month, day.day, 0, 0, 0, tzinfo=datetime.timezone.utc)
        candles.append([_iso(ts), round(open_p, 2), round(high_p, 2), round(low_p, 2), round(close_p, 2), vol])
        cur = close_p

    payload = {"candles": candles, "instrument_token": instrument_token, "interval": interval}
    req_row["response_payload"] = payload

    reqs.append(req_row)
    _save("market_data_requests.json", reqs)

    _audit("ok", meta={"market_data_request_id": req_row["id"], "used_auth_session_id": sess.get("id"), "candles": len(candles)})
    return {"data": payload, "market_data_request": req_row}

def get_mf_orders(user_id, auth_session_id=None, status=None, upstream_order_id=None, tradingsymbol=None, tag=None, created_after=None, created_before=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_mf_orders"
    used_cred = auth_session_id

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _audit(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": f"zui_req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "credential": used_cred,
            "status": status_s,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now(),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[0-9A-Z]+\.?[0-9A-Z]*.*$", user_id):
        e = _err("VALIDATION_ERROR", "Invalid user_id format.", field="user_id")
        _audit("error", e["error"])
        return e
    if auth_session_id is not None:
        if not isinstance(auth_session_id, str) or not re.match(r"^zui_sess_[0-9A-Z]+\.?[0-9A-Z]*.*$", auth_session_id):
            e = _err("VALIDATION_ERROR", "Invalid auth_session_id format.", field="auth_session_id")
            _audit("error", e["error"])
            return e
    allowed_status = {"created","submitted","accepted","rejected","cancelled","completed","active","paused","failed"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        e = _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
        _audit("error", e["error"])
        return e
    if upstream_order_id is not None and not isinstance(upstream_order_id, str):
        e = _err("VALIDATION_ERROR", "upstream_order_id must be a string.", field="upstream_order_id")
        _audit("error", e["error"])
        return e
    if tradingsymbol is not None and not isinstance(tradingsymbol, str):
        e = _err("VALIDATION_ERROR", "tradingsymbol must be a string.", field="tradingsymbol")
        _audit("error", e["error"])
        return e
    if tag is not None and not isinstance(tag, str):
        e = _err("VALIDATION_ERROR", "tag must be a string.", field="tag")
        _audit("error", e["error"])
        return e

    da = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and da is None:
        e = _err("VALIDATION_ERROR", "created_after must be an ISO date-time string.", field="created_after")
        _audit("error", e["error"])
        return e
    db = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and db is None:
        e = _err("VALIDATION_ERROR", "created_before must be an ISO date-time string.", field="created_before")
        _audit("error", e["error"])
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        _audit("error", e["error"])
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        _audit("error", e["error"])
        return e
    if sort is None:
        sort = "-created_at"
    if sort not in {"created_at","-created_at","updated_at","-updated_at"}:
        e = _err("VALIDATION_ERROR", "Invalid sort value.", field="sort")
        _audit("error", e["error"])
        return e

    users = _load("users.json")
    user = next((u for u in users if u.get("id") == user_id), None)
    if not user or user.get("status") == "deleted":
        e = _err("NOT_FOUND", "User not found.", user_id=user_id)
        _audit("error", e["error"])
        return e

    sessions = _load("auth_sessions.json")
    if auth_session_id is not None:
        sess = next((s for s in sessions if s.get("id") == auth_session_id and s.get("user_id") == user_id), None)
        if not sess:
            e = _err("UNAUTHORIZED", "auth_session_id is not valid for the given user.", auth_session_id=auth_session_id)
            _audit("error", e["error"])
            return e

    orders = _load("orders.json")
    rows = [o for o in orders if o.get("user_id") == user_id and o.get("order_domain") == "mf_order"]

    if auth_session_id is not None:
        rows = [o for o in rows if o.get("auth_session_id") == auth_session_id]

    if status is not None:
        rows = [o for o in rows if o.get("status") == status]
    if upstream_order_id is not None:
        rows = [o for o in rows if o.get("upstream_order_id") == upstream_order_id]
    if tradingsymbol is not None:
        rows = [o for o in rows if o.get("tradingsymbol") == tradingsymbol]
    if tag is not None:
        rows = [o for o in rows if o.get("tag") == tag]
    if da is not None:
        rows = [o for o in rows if (_parse_dt(o.get("created_at")) or datetime.datetime.min) >= da]
    if db is not None:
        rows = [o for o in rows if (_parse_dt(o.get("created_at")) or datetime.datetime.max) <= db]

    reverse = sort.startswith("-")
    sort_key = sort[1:] if reverse else sort

    def _skey(o):
        d = _parse_dt(o.get(sort_key))
        return d or datetime.datetime.min

    rows.sort(key=_skey, reverse=reverse)

    # Cursor is base64 of {"offset": int}
    offset = 0
    if cursor:
        try:
            payload = json.loads(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
            if not isinstance(payload, dict) or not isinstance(payload.get("offset"), int) or payload["offset"] < 0:
                raise ValueError("bad cursor")
            offset = payload["offset"]
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _audit("error", e["error"])
            return e

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8")

    resp = {
        "object": "list",
        "data": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
    }
    _audit("ok", meta={"returned": len(page), "total": total})
    return resp

def place_mf_order(user_id, auth_session_id, tradingsymbol, transaction_type, amount, tag=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "place_mf_order"
    used_cred = auth_session_id

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now_dt()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
