        "upstream_status": "submitted",
        "last_error_message": None,
        "request_payload": {
            "tradingsymbol": tradingsymbol,
            "transaction_type": transaction_type,
            "amount": float(amount),
            "tag": tag,
        },
        "response_payload": {"status": "success", "order_id": upstream_order_id},
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    orders.append(order_row)
    _save("orders.json", orders)

    _audit("ok", meta={"order_id": order_row["id"], "upstream_order_id": upstream_order_id, "used_auth_session_id": sess.get("id")})
    return {"order": order_row}

def cancel_mf_order(user_id, auth_session_id, order_id, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel_mf_order"
    used_cred = auth_session_id

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(st)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _audit(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "credential": used_cred,
            "status": status_s,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Validate inputs (accept either local id or upstream id for compatibility with real usage)
    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[0-9A-Za-z]+.*$", user_id):
        e = _err("VALIDATION_ERROR", "user_id is malformed", field="user_id")
        _audit("error", e["error"])
        return e
    if not isinstance(auth_session_id, str) or not re.match(r"^zui_sess_[0-9A-Za-z]+.*$", auth_session_id):
        e = _err("VALIDATION_ERROR", "auth_session_id is malformed", field="auth_session_id")
        _audit("error", e["error"])
        return e
    if not isinstance(order_id, str) or not order_id.strip():
        e = _err("VALIDATION_ERROR", "order_id is required", field="order_id")
        _audit("error", e["error"])
        return e
    order_id = order_id.strip()

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not user:
        e = _err("NOT_FOUND", "User not found", user_id=user_id)
        _audit("error", e["error"])
        return e
    if user.get("status") != "active":
        e = _err("CONFLICT", "User is not active", user_id=user_id, status=user.get("status"))
        _audit("error", e["error"])
        return e

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == auth_session_id and s.get("user_id") == user_id), None)
    if not sess:
        e = _err("UNAUTHORIZED", "auth_session_id is not valid for the given user_id", user_id=user_id, auth_session_id=auth_session_id)
        _audit("error", e["error"])
        return e

    now = _now()
    expires = _parse_dt(sess.get("access_token_expires_at"))
    if sess.get("status") != "authenticated" or not expires or expires <= now or not isinstance(sess.get("access_token"), str) or len(sess.get("access_token")) < 10:
        e = _err(
            "UNAUTHORIZED",
            "Authenticated session is required and must not be expired. Run check_and_authenticate/initiate_login to re-authenticate.",
            user_id=user_id,
            auth_session_id=auth_session_id,
            session_status=sess.get("status"),
            access_token_expires_at=sess.get("access_token_expires_at"),
        )
        _audit("error", e["error"])
        return e

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    # Find order by local id OR by upstream_order_id (real clients often pass upstream ids)
    idx = None
    for i, o in enumerate(orders):
        if not isinstance(o, dict):
            continue
        if o.get("user_id") != user_id:
            continue
        if o.get("order_domain") != "mf_order":
            continue
        if o.get("id") == order_id or o.get("upstream_order_id") == order_id:
            idx = i
            break

    if idx is None:
        e = _err("NOT_FOUND", "Mutual-fund order not found", user_id=user_id, order_id=order_id)
        _audit("error", e["error"])
        return e

    order = orders[idx]

    # Must be cancellable
    if order.get("status") not in ("submitted", "accepted"):
        e = _err(
            "CONFLICT",
            "MF order is not cancellable in its current status; allowed statuses: submitted, accepted.",
            order_id=order.get("id"),
            upstream_order_id=order.get("upstream_order_id"),
            current_status=order.get("status"),
        )
        _audit("error", e["error"])
        return e

    # Lifecycle transition check
    allowed = {"submitted": ["accepted", "rejected", "failed"], "accepted": ["completed", "cancelled", "failed"]}
    cur = order.get("status")
    if "cancelled" not in allowed.get(cur, []):
        e = _err("INVALID_TRANSITION", "Order cannot transition to cancelled from current status", order_id=order.get("id"), from_status=cur, to_status="cancelled")
        _audit("error", e["error"])
        return e

    # "Call upstream": offline implementation records a successful cancel with response metadata.
    # Idempotency: if already cancelled, would have been caught above; here we actually effect change.
    now_iso = _iso(now)
    upstream_resp = {
        "ok": True,
        "action": "cancel_mf_order",
        "upstream_order_id": order.get("upstream_order_id"),
        "cancelled_at": now_iso,
    }

    order["auth_session_id"] = auth_session_id
    order["status"] = "cancelled"
    order["upstream_status"] = "CANCELLED"
    order["last_error_message"] = None
    order["response_payload"] = upstream_resp
    order["updated_at"] = now_iso
    orders[idx] = order
    _save("orders.json", orders)

    _audit("ok", meta={"order_id": order.get("id"), "upstream_order_id": order.get("upstream_order_id")})
    return {"order": order}

def get_mf_instruments(status=None, amc=None, tradingsymbol=None, query=None, is_purchase_allowed=None, is_redemption_allowed=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # ---- request logging + quota ----
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    # Simple daily quota per endpoint (since schema not provided)
    daily_quota = 5000
    day_key = now.strftime("%Y-%m-%d")
    used_today = 0
    for r in logs:
        if isinstance(r, dict) and r.get("endpoint") == "get_mf_instruments":
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts[:10] == day_key:
                used_today += 1
    if used_today >= daily_quota:
        # log refusal
        logs.append({
            "id": f"zui_req_{int(time.time()*1000)}",
            "endpoint": "get_mf_instruments",
            "credential": None,
            "status": "error",
            "error_code": "QUOTA_EXCEEDED",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat()
        })
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for get_mf_instruments", quota=daily_quota, used=used_today)

    # ---- validations ----
    if status is not None and (not isinstance(status, str) or status not in ("active", "inactive")):
        return _err("VALIDATION_ERROR", "Invalid status; must be one of: active, inactive")
    if amc is not None and not isinstance(amc, str):
        return _err("VALIDATION_ERROR", "amc must be a string")
    if tradingsymbol is not None and not isinstance(tradingsymbol, str):
        return _err("VALIDATION_ERROR", "tradingsymbol must be a string")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    if is_purchase_allowed is not None and not isinstance(is_purchase_allowed, bool):
        return _err("VALIDATION_ERROR", "is_purchase_allowed must be a boolean")
    if is_redemption_allowed is not None and not isinstance(is_redemption_allowed, bool):
        return _err("VALIDATION_ERROR", "is_redemption_allowed must be a boolean")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")

    if sort is None:
        sort = "tradingsymbol"
    if not isinstance(sort, str) or sort not in ("tradingsymbol", "-tradingsymbol", "name", "-name", "last_refreshed_at", "-last_refreshed_at"):
        return _err("VALIDATION_ERROR", "Invalid sort")

    # Cursor format: base64url("v1:<offset:int>")
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) < 1:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            if not raw.startswith("v1:"):
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            return _err("VALIDATION_ERROR", "Invalid cursor")

    instruments = _load("mf_instruments.json")
    if not isinstance(instruments, list):
        instruments = []

    # ---- filtering ----
    q = query.lower().strip() if isinstance(query, str) else None
    amc_q = amc.lower().strip() if isinstance(amc, str) else None
    ts_exact = tradingsymbol.strip() if isinstance(tradingsymbol, str) else None

    out = []
    for row in instruments:
        if not isinstance(row, dict):
            continue
        if status is not None and row.get("status") != status:
            continue
        if amc_q is not None:
            v = row.get("amc")
            if not isinstance(v, str) or v.lower().strip() != amc_q:
                continue
        if ts_exact is not None:
            if row.get("tradingsymbol") != ts_exact:
                continue
        if is_purchase_allowed is not None:
            if row.get("is_purchase_allowed") is None:
                continue
            if bool(row.get("is_purchase_allowed")) != is_purchase_allowed:
                continue
        if is_redemption_allowed is not None:
            if row.get("is_redemption_allowed") is None:
                continue
            if bool(row.get("is_redemption_allowed")) != is_redemption_allowed:
                continue
        if q is not None and q != "":
            hay = " ".join([
                str(row.get("tradingsymbol") or ""),
                str(row.get("amc") or ""),
                str(row.get("name") or ""),
            ]).lower()
            if q not in hay:
                continue
        out.append(row)

    # ---- sort ----
    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None

    def _k(r):
        if key in ("tradingsymbol", "name"):
            v = r.get(key)
            return ("" if v is None else str(v)).lower()
        if key == "last_refreshed_at":
            d = _dt(r.get("last_refreshed_at"))
            return d if d is not None else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return ""

    out.sort(key=_k, reverse=desc)

    total = len(out)
    page = out[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        token = f"v1:{next_offset}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    body = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

    logs.append({
        "id": f"zui_req_{int(time.time()*1000)}",
        "endpoint": "get_mf_instruments",
        "credential": None,
        "status": "ok",
        "latency_ms": int((time.time() - t0) * 1000),
        "timestamp": now.isoformat()
    })
    _save("request_logs.json", logs)
    return body

def get_mf_holdings(user_id, auth_session_id, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_mf_holdings"
    used_cred = auth_session_id

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now_dt()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(st)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _audit(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "credential": used_cred,
            "status": status_s,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now_dt()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Validate ids (pattern in tool schema is broader; accept any zui_usr_/zui_sess_ prefix)
    if not isinstance(user_id, str) or not user_id.startswith("zui_usr_"):
        e = _err("VALIDATION_ERROR", "Invalid user_id format", field="user_id")
        _audit("error", e["error"])
        return e
    if not isinstance(auth_session_id, str) or not auth_session_id.startswith("zui_sess_"):
        e = _err("VALIDATION_ERROR", "Invalid auth_session_id format", field="auth_session_id")
        _audit("error", e["error"])
        return e

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not user:
        e = _err("NOT_FOUND", "User not found", user_id=user_id)
        _audit("error", e["error"])
        return e
    if user.get("status") != "active":
        e = _err("CONFLICT", "User is not active", user_id=user_id, status=user.get("status"))
        _audit("error", e["error"])
        return e

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == auth_session_id), None)
    if not sess:
        e = _err("NOT_FOUND", "auth_session_id not found", auth_session_id=auth_session_id)
        _audit("error", e["error"])
        return e

    now = _now_dt()
    exp = _parse_dt(sess.get("access_token_expires_at"))
    if sess.get("status") != "authenticated" or not exp or exp <= now:
        # fallback to any authenticated, non-expired session for this user
        def _sess_created_at(s):
            dt = _parse_dt(s.get("created_at"))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        candidates = [
            s for s in sessions
            if isinstance(s, dict)
            and s.get("user_id") == user_id
            and s.get("status") == "authenticated"
            and (_parse_dt(s.get("access_token_expires_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) > now
        ]
        if candidates:
            sess = sorted(candidates, key=_sess_created_at, reverse=True)[0]
            used_cred = sess.get("id")
        else:
            e = _err(
                "CONFLICT",
                "No active authenticated session for user. Re-authentication required via initiate_login.",
                rule="Upstream calls require auth_sessions.status='authenticated' and access_token_expires_at > now()",
                user_id=user_id,
                auth_session_id=auth_session_id,
            )
            _audit("error", e["error"])
            return e

    # Persist a portfolio snapshot of type "holdings" (closest available store for MF holdings mirror)
    snaps = _load("portfolio_snapshots.json")
    if not isinstance(snaps, list):
        snaps = []

    now_iso = _iso(now)

    # Derive a simple MF holdings view from mf_order/mf_sip orders (offline mirror)
    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    mf_orders = [o for o in orders if isinstance(o, dict) and o.get("user_id") == user_id and o.get("order_domain") in ("mf_order", "mf_sip")]
    holdings = {}
    for o in mf_orders:
        ts = o.get("tradingsymbol")
        if not ts:
            continue
        amt = o.get("amount") if isinstance(o.get("amount"), (int, float)) and not isinstance(o.get("amount"), bool) else 0.0
        side = o.get("transaction_type")
        # For SIPs, treat amount as recurring; for a snapshot, aggregate configured amount
        if o.get("order_domain") == "mf_sip" and o.get("status") in ("active", "paused", "created", "submitted"):
            amt_effective = float(amt)
        else:
            amt_effective = float(amt)
        if side == "SELL":
            amt_effective = -abs(amt_effective)
        else:
            amt_effective = abs(amt_effective)
        holdings.setdefault(ts, 0.0)
        holdings[ts] += amt_effective

    payload = {
        "mf_holdings": [{"tradingsymbol": k, "net_amount": round(v, 2)} for k, v in sorted(holdings.items())],
        "source": "kite_api",
        "note": "Offline mirror derived from local mf_order/mf_sip records.",
    }

    snap_row = {
        "id": f"zui_pfs_{secrets.token_hex(12)}",
        "user_id": user_id,
        "auth_session_id": sess.get("id"),
        "snapshot_type": "holdings",
        "as_of": now_iso,
        "status": "fresh",
        "payload": payload,
        "source": "kite_api",
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    snaps.append(snap_row)
    _save("portfolio_snapshots.json", snaps)

    _audit("ok", meta={"portfolio_snapshot_id": snap_row["id"], "used_auth_session_id": sess.get("id")})
    return {"snapshot": snap_row}

