        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for get_mf_sips", quota=daily_quota, used=used_today)

    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[0-9A-Z]+\.?[0-9A-Z]*.*$", user_id):
        return _err("VALIDATION_ERROR", "Invalid user_id format")

    if auth_session_id is not None:
        if not isinstance(auth_session_id, str) or not re.match(r"^zui_sess_[0-9A-Z]+\.?[0-9A-Z]*.*$", auth_session_id):
            return _err("VALIDATION_ERROR", "Invalid auth_session_id format")

    valid_status = ("created", "submitted", "accepted", "rejected", "cancelled", "completed", "active", "paused", "failed")
    if status is not None and (not isinstance(status, str) or status not in valid_status):
        return _err("VALIDATION_ERROR", "Invalid status filter")
    if upstream_sip_id is not None and not isinstance(upstream_sip_id, str):
        return _err("VALIDATION_ERROR", "upstream_sip_id must be a string")
    if tradingsymbol is not None and not isinstance(tradingsymbol, str):
        return _err("VALIDATION_ERROR", "tradingsymbol must be a string")
    if frequency is not None and (not isinstance(frequency, str) or frequency not in ("weekly", "monthly", "quarterly")):
        return _err("VALIDATION_ERROR", "Invalid frequency filter")
    if tag is not None and not isinstance(tag, str):
        return _err("VALIDATION_ERROR", "tag must be a string")

    def _parse_dt(x, field):
        if x is None:
            return None
        if not isinstance(x, str):
            raise ValueError(field)
        try:
            return datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
        except ValueError:
            raise ValueError(field)

    try:
        ca = _parse_dt(created_after, "created_after")
        cb = _parse_dt(created_before, "created_before")
    except ValueError as e:
        return _err("VALIDATION_ERROR", f"Malformed timestamp for {str(e)}")
    if ca is not None and cb is not None and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "-created_at", "updated_at", "-updated_at"):
        return _err("VALIDATION_ERROR", "Invalid sort")

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) < 1:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            if not raw.startswith("v1:"):
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # If auth_session_id provided, validate it belongs to user (scoping)
    if auth_session_id is not None:
        sessions = _load("auth_sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == auth_session_id), None)
        if sess is None or sess.get("user_id") != user_id:
            return _err("UNAUTHORIZED", "Auth session invalid for user", auth_session_id=auth_session_id, user_id=user_id)

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None

    rows = []
    for o in orders:
        if not isinstance(o, dict):
            continue
        if o.get("order_domain") != "mf_sip":
            continue
        if o.get("user_id") != user_id:
            continue
        if auth_session_id is not None and o.get("auth_session_id") != auth_session_id:
            continue
        if status is not None and o.get("status") != status:
            continue
        if upstream_sip_id is not None and o.get("upstream_sip_id") != upstream_sip_id:
            continue
        if tradingsymbol is not None and o.get("tradingsymbol") != tradingsymbol:
            continue
        if frequency is not None and o.get("frequency") != frequency:
            continue
        if tag is not None and o.get("tag") != tag:
            continue
        created_dt = _dt(o.get("created_at"))
        if ca is not None:
            if created_dt is None or created_dt < ca:
                continue
        if cb is not None:
            if created_dt is None or created_dt > cb:
                continue
        rows.append(o)

    desc = sort.startswith("-")
    sort_key = sort[1:] if desc else sort

    def _k(r):
        d = _dt(r.get(sort_key))
        return d if d is not None else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    rows.sort(key=_k, reverse=desc)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        token = f"v1:{next_offset}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    body = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

    logs.append({
        "id": f"zui_req_{int(time.time()*1000)}",
        "endpoint": "get_mf_sips",
        "credential": auth_session_id,
        "status": "ok",
        "latency_ms": int((time.time() - t0) * 1000),
        "timestamp": now.isoformat()
    })
    _save("request_logs.json", logs)
    return body

def place_mf_sip(user_id, auth_session_id, tradingsymbol, amount, instalments, frequency, initial_amount=None, instalment_day=None, tag=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "place_mf_sip"
    used_cred = auth_session_id

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now_dt()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(st)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _audit(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "credential": used_cred,
            "status": status_s,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now_dt()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(user_id, str) or not user_id.startswith("zui_usr_"):
        e = _err("VALIDATION_ERROR", "Invalid user_id format", field="user_id")
        _audit("error", e["error"])
        return e
    if not isinstance(auth_session_id, str) or not auth_session_id.startswith("zui_sess_"):
        e = _err("VALIDATION_ERROR", "Invalid auth_session_id format", field="auth_session_id")
        _audit("error", e["error"])
        return e
    if not isinstance(tradingsymbol, str) or not tradingsymbol.strip():
        e = _err("VALIDATION_ERROR", "tradingsymbol must be a non-empty string", field="tradingsymbol")
        _audit("error", e["error"])
        return e
    if not isinstance(amount, (int, float)) or isinstance(amount, bool) or amount <= 0:
        e = _err("VALIDATION_ERROR", "amount must be a number > 0", field="amount")
        _audit("error", e["error"])
        return e
    if not isinstance(instalments, int) or isinstance(instalments, bool) or instalments < 6:
        e = _err("VALIDATION_ERROR", "instalments must be an integer >= 6", field="instalments")
        _audit("error", e["error"])
        return e
    if frequency not in ("weekly", "monthly", "quarterly"):
        e = _err("VALIDATION_ERROR", "frequency must be one of weekly, monthly, quarterly", field="frequency")
        _audit("error", e["error"])
        return e
    if initial_amount is not None and (not isinstance(initial_amount, (int, float)) or isinstance(initial_amount, bool) or initial_amount <= 0):
        e = _err("VALIDATION_ERROR", "initial_amount must be a number > 0", field="initial_amount")
        _audit("error", e["error"])
        return e
    if instalment_day is not None:
        if not isinstance(instalment_day, int) or isinstance(instalment_day, bool) or instalment_day < 1 or instalment_day > 31:
            e = _err("VALIDATION_ERROR", "instalment_day must be an integer between 1 and 31", field="instalment_day")
            _audit("error", e["error"])
            return e
        if frequency == "weekly" and instalment_day > 7:
            e = _err("VALIDATION_ERROR", "For weekly SIPs, instalment_day must be between 1 and 7", field="instalment_day")
            _audit("error", e["error"])
            return e
    if tag is not None and (not isinstance(tag, str) or len(tag) > 256):
        e = _err("VALIDATION_ERROR", "tag must be a string up to 256 characters", field="tag")
        _audit("error", e["error"])
        return e

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not user:
        e = _err("NOT_FOUND", "User not found", user_id=user_id)
        _audit("error", e["error"])
        return e
    if user.get("status") != "active":
        e = _err("CONFLICT", "User is not active", user_id=user_id, status=user.get("status"))
        _audit("error", e["error"])
        return e

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == auth_session_id), None)
    if not sess:
        e = _err("NOT_FOUND", "auth_session_id not found", auth_session_id=auth_session_id)
        _audit("error", e["error"])
        return e

    now = _now_dt()
    exp = _parse_dt(sess.get("access_token_expires_at"))
    if sess.get("status") != "authenticated" or not exp or exp <= now:
        def _sess_created_at(s):
            dt = _parse_dt(s.get("created_at"))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        candidates = [
            s for s in sessions
            if isinstance(s, dict)
            and s.get("user_id") == user_id
            and s.get("status") == "authenticated"
            and (_parse_dt(s.get("access_token_expires_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) > now
        ]
        if candidates:
            sess = sorted(candidates, key=_sess_created_at, reverse=True)[0]
            used_cred = sess.get("id")
        else:
            e = _err(
                "CONFLICT",
                "No active authenticated session for user. Re-authentication required via initiate_login.",
                rule="Upstream calls require auth_sessions.status='authenticated' and access_token_expires_at > now()",
                user_id=user_id,
                auth_session_id=auth_session_id,
            )
            _audit("error", e["error"])
            return e

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    upstream_sip_id = f"sip_{secrets.token_hex(8)}"
    if any(isinstance(o, dict) and o.get("upstream_sip_id") == upstream_sip_id for o in orders):
        upstream_sip_id = f"sip_{secrets.token_hex(9)}"

    now_iso = _iso(now)
    sip_row = {
        "id": f"zui_ord_{secrets.token_hex(12)}",
        "user_id": user_id,
        "auth_session_id": sess.get("id"),
        "order_domain": "mf_sip",
        "upstream_order_id": None,
        "upstream_sip_id": upstream_sip_id,
        "tradingsymbol": tradingsymbol,
        "exchange": None,
        "transaction_type": None,
        "quantity": None,
        "product": None,
        "order_type": None,
        "price": None,
        "trigger_price": None,
        "amount": float(amount),
        "frequency": frequency,
        "instalments": int(instalments),
        "initial_amount": float(initial_amount) if initial_amount is not None else None,
        "instalment_day": int(instalment_day) if instalment_day is not None else None,
        "tag": tag,
        "status": "active",
        "upstream_status": "active",
        "last_error_message": None,
        "request_payload": {
            "tradingsymbol": tradingsymbol,
            "amount": float(amount),
            "instalments": int(instalments),
            "frequency": frequency,
            "initial_amount": float(initial_amount) if initial_amount is not None else None,
            "instalment_day": int(instalment_day) if instalment_day is not None else None,
            "tag": tag,
        },
        "response_payload": {"status": "success", "sip_id": upstream_sip_id},
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    orders.append(sip_row)
    _save("orders.json", orders)
    _audit("ok", meta={"sip_order_id": sip_row["id"], "upstream_sip_id": upstream_sip_id, "used_auth_session_id": sess.get("id")})
    return {"order": sip_row}

def modify_mf_sip(sip_id, amount=None, frequency=None, instalments=None, instalment_day=None, status=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "modify_mf_sip"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _audit(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "credential": None,
            "status": status_s,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # sip_id validation: accept both local ids and real upstream SIP ids (e.g. SIP2406...)
    if not isinstance(sip_id, str) or not sip_id.strip():
        e = _err("VALIDATION_ERROR", "sip_id is required", field="sip_id")
        _audit("error", e["error"])
        return e
    sip_id = sip_id.strip()
    if not (re.match(r"^zui_ord_[0-9A-Za-z]+$", sip_id) or re.match(r"^SIP[0-9A-Za-z]+$", sip_id)):
        e = _err("VALIDATION_ERROR", "sip_id is malformed", field="sip_id")
        _audit("error", e["error"])
        return e

    provided = {k: v for k, v in {
        "amount": amount,
        "frequency": frequency,
        "instalments": instalments,
        "instalment_day": instalment_day,
        "status": status,
    }.items() if v is not None}
    if not provided:
        e = _err(
            "VALIDATION_ERROR",
            "No modifiable fields provided. Provide at least one of amount, frequency, instalments, instalment_day, status.",
        )
        _audit("error", e["error"])
        return e

    if amount is not None and (not isinstance(amount, (int, float)) or isinstance(amount, bool) or amount <= 0):
        e = _err("VALIDATION_ERROR", "amount must be a number > 0", field="amount")
        _audit("error", e["error"])
        return e
    if frequency is not None and frequency not in ("weekly", "monthly", "quarterly"):
        e = _err("VALIDATION_ERROR", "frequency must be one of weekly, monthly, quarterly", field="frequency")
        _audit("error", e["error"])
        return e
    if instalments is not None and (not isinstance(instalments, int) or isinstance(instalments, bool) or instalments < 1):
        e = _err("VALIDATION_ERROR", "instalments must be an integer >= 1", field="instalments")
        _audit("error", e["error"])
        return e
    if instalment_day is not None and (not isinstance(instalment_day, int) or isinstance(instalment_day, bool) or instalment_day < 1 or instalment_day > 31):
        e = _err("VALIDATION_ERROR", "instalment_day must be an integer between 1 and 31", field="instalment_day")
        _audit("error", e["error"])
        return e
    if status is not None and status not in ("active", "paused"):
        e = _err("VALIDATION_ERROR", "status must be one of active, paused", field="status")
        _audit("error", e["error"])
        return e

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    # locate by local id or upstream_sip_id
    idx = None
    for i, o in enumerate(orders):
        if not isinstance(o, dict):
            continue
        if o.get("order_domain") != "mf_sip":
            continue
        if o.get("id") == sip_id or o.get("upstream_sip_id") == sip_id:
            idx = i
            break
    if idx is None:
        e = _err("NOT_FOUND", "SIP not found", sip_id=sip_id)
        _audit("error", e["error"])
        return e

    order = orders[idx]
    if order.get("order_domain") != "mf_sip":
        e = _err("NOT_FOUND", "SIP not found", sip_id=sip_id)
        _audit("error", e["error"])
        return e

    # must have upstream_sip_id and be modifiable
    if not isinstance(order.get("upstream_sip_id"), str) or not order.get("upstream_sip_id"):
        e = _err("CONFLICT", "SIP is missing upstream_sip_id and cannot be modified upstream", sip_id=order.get("id"))
        _audit("error", e["error"])
        return e
    if order.get("status") not in ("active", "paused"):
        e = _err("CONFLICT", "SIP is not modifiable in its current status; allowed statuses: active, paused.", sip_id=order.get("id"), current_status=order.get("status"))
        _audit("error", e["error"])
        return e

    # enforce mf_sip constraints on modified values (amount>0; instalments>=6; frequency required)
    new_amount = order.get("amount") if amount is None else float(amount)
    new_freq = order.get("frequency") if frequency is None else frequency
    new_instal = order.get("instalments") if instalments is None else instalments
    if new_amount is None or new_amount <= 0:
        e = _err("VALIDATION_ERROR", "mf_sip requires amount > 0", field="amount")
        _audit("error", e["error"])
        return e
    if new_freq is None or new_freq not in ("weekly", "monthly", "quarterly"):
        e = _err("VALIDATION_ERROR", "mf_sip requires frequency in (weekly, monthly, quarterly)", field="frequency")
        _audit("error", e["error"])
        return e
    if new_instal is None or not isinstance(new_instal, int) or new_instal < 6:
        e = _err("VALIDATION_ERROR", "mf_sip requires instalments >= 6", field="instalments")
        _audit("error", e["error"])
        return e

    # status transition active <-> paused only
    if status is not None and status != order.get("status"):
        allowed = {"active": ["paused", "cancelled", "completed", "failed"], "paused": ["active", "cancelled", "failed"]}
        if status not in allowed.get(order.get("status"), []):
            e = _err("INVALID_TRANSITION", "SIP cannot transition to requested status", sip_id=order.get("id"), from_status=order.get("status"), to_status=status)
            _audit("error", e["error"])
            return e

    # Idempotency: if provided fields don't change anything, treat as conflict (no success without effect)
    changes = {}
    if amount is not None and float(order.get("amount") or 0) != float(amount):
        changes["amount"] = float(amount)
    if frequency is not None and order.get("frequency") != frequency:
        changes["frequency"] = frequency
    if instalments is not None and order.get("instalments") != instalments:
        changes["instalments"] = instalments
    if instalment_day is not None and order.get("instalment_day") != instalment_day:
        changes["instalment_day"] = instalment_day
    if status is not None and order.get("status") != status:
        changes["status"] = status
    if not changes:
        e = _err("CONFLICT", "No changes to apply; all provided fields match current values.", sip_id=order.get("id"))
        _audit("error", e["error"])
        return e

    # "Call upstream": offline success response
    now_iso = _iso(_now())
    upstream_resp = {
        "ok": True,
        "action": "modify_mf_sip",
        "upstream_sip_id": order.get("upstream_sip_id"),
        "applied": changes,
        "modified_at": now_iso,
    }

    # Apply changes locally
    if "amount" in changes:
        order["amount"] = changes["amount"]
    if "frequency" in changes:
        order["frequency"] = changes["frequency"]
    if "instalments" in changes:
        order["instalments"] = changes["instalments"]
    if "instalment_day" in changes:
        order["instalment_day"] = changes["instalment_day"]
    if "status" in changes:
        order["status"] = changes["status"]
        order["upstream_status"] = changes["status"].upper()
    order["response_payload"] = upstream_resp
    order["last_error_message"] = None
    order["updated_at"] = now_iso

    orders[idx] = order
    _save("orders.json", orders)

    _audit("ok", meta={"sip_id": order.get("id"), "upstream_sip_id": order.get("upstream_sip_id"), "changes": list(changes.keys())})
    return {"sip": order}

def cancel_mf_sip(sip_id, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel_mf_sip"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _audit(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "credential": None,
            "status": status_s,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if not isinstance(sip_id, str) or not sip_id.strip():
        e = _err("VALIDATION_ERROR", "sip_id is required", field="sip_id")
        _audit("error", e["error"])
        return e
    sip_id = sip_id.strip()
    if not (re.match(r"^zui_ord_[0-9A-Za-z]+$", sip_id) or re.match(r"^SIP[0-9A-Za-z]+$", sip_id)):
        e = _err("VALIDATION_ERROR", "sip_id is malformed", field="sip_id")
        _audit("error", e["error"])
        return e

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    idx = None
    for i, o in enumerate(orders):
        if not isinstance(o, dict):
            continue
        if o.get("order_domain") != "mf_sip":
            continue
        if o.get("id") == sip_id or o.get("upstream_sip_id") == sip_id:
            idx = i
            break

    if idx is None:
        e = _err("NOT_FOUND", "SIP not found", sip_id=sip_id)
        _audit("error", e["error"])
        return e

    order = orders[idx]
    if order.get("order_domain") != "mf_sip":
        e = _err("NOT_FOUND", "SIP not found", sip_id=sip_id)
        _audit("error", e["error"])
        return e

    if order.get("status") in ("cancelled", "completed", "rejected"):
        e = _err("CONFLICT", "SIP is not cancellable in its current status", sip_id=order.get("id"), current_status=order.get("status"))
        _audit("error", e["error"])
        return e

    # lifecycle transition check (from active/paused only, per schema)
    cur = order.get("status")
    allowed = {"active": ["paused", "cancelled", "completed", "failed"], "paused": ["active", "cancelled", "failed"]}
    if "cancelled" not in allowed.get(cur, []):
        e = _err("INVALID_TRANSITION", "SIP cannot transition to cancelled from current status", sip_id=order.get("id"), from_status=cur, to_status="cancelled")
        _audit("error", e["error"])
        return e

    now_iso = _iso(_now())
    upstream_resp = {
        "ok": True,
        "action": "cancel_mf_sip",
        "upstream_sip_id": order.get("upstream_sip_id"),
        "cancelled_at": now_iso,
    }

    order["status"] = "cancelled"
    order["upstream_status"] = "CANCELLED"
    order["last_error_message"] = None
    order["response_payload"] = upstream_resp
    order["updated_at"] = now_iso
    orders[idx] = order
    _save("orders.json", orders)

    _audit("ok", meta={"sip_id": order.get("id"), "upstream_sip_id": order.get("upstream_sip_id")})
    return {"sip": order}

def list_orders(user_id, order_domain=None, status=None, upstream_order_id=None, upstream_sip_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _encode_cursor(created_at, oid):
        raw = json.dumps({"created_at": created_at, "id": oid}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if not isinstance(c, str) or not c:
            return None
        pad = "=" * ((4 - (len(c) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if "created_at" not in obj or "id" not in obj:
                return None
            if not isinstance(obj["created_at"], str) or not isinstance(obj["id"], str):
                return None
            return obj
        except Exception:
            return None

    t0 = time.time()

    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[A-Za-z0-9]+$", user_id):
        return _err("VALIDATION_ERROR", "user_id is malformed", field="user_id")

    if order_domain is not None:
        if not isinstance(order_domain, str) or order_domain not in ("kite_order", "mf_order", "mf_sip"):
            return _err("VALIDATION_ERROR", "order_domain must be one of kite_order, mf_order, mf_sip", field="order_domain")

    if status is not None:
        allowed_status = ("created", "submitted", "accepted", "rejected", "cancelled", "completed", "active", "paused", "failed")
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status is invalid", field="status")

    if upstream_order_id is not None and not isinstance(upstream_order_id, str):
        return _err("VALIDATION_ERROR", "upstream_order_id must be a string", field="upstream_order_id")
    if upstream_sip_id is not None and not isinstance(upstream_sip_id, str):
        return _err("VALIDATION_ERROR", "upstream_sip_id must be a string", field="upstream_sip_id")

    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an ISO 8601 date-time string", field="created_after")
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an ISO 8601 date-time string", field="created_before")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    cur = _decode_cursor(cursor) if cursor is not None else None
    if cursor is not None and cur is None:
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    users = _load("users.json")
    orders = _load("orders.json")

    user = next((u for u in users if u.get("id") == user_id), None)
    if user is None or user.get("status") == "deleted":
        return _err("NOT_FOUND", "User not found", user_id=user_id)

    # Ambient auth: no explicit credentials in params; allow if user exists.
    # If user suspended, still allow listing (no rule forbids); if desired could be conflict. We'll allow.

    filtered = []
    for o in orders:
        if o.get("user_id") != user_id:
            continue
        if order_domain is not None and o.get("order_domain") != order_domain:
            continue
        if status is not None and o.get("status") != status:
            continue
        if upstream_order_id is not None and o.get("upstream_order_id") != upstream_order_id:
            continue
        if upstream_sip_id is not None and o.get("upstream_sip_id") != upstream_sip_id:
            continue

        o_created = _parse_dt(o.get("created_at"))
        if ca is not None and o_created is not None and o_created < ca:
            continue
        if cb is not None and o_created is not None and o_created > cb:
            continue

        filtered.append(o)

    # Sort reverse chronological by created_at then id
    def _sort_key(o):
        dt = _parse_dt(o.get("created_at"))
        # None sorts last
        ts = dt.timestamp() if dt is not None else -1e30
        return (ts, o.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor as "start after this item" in the sorted order
    if cur is not None:
        anchor_created = cur["created_at"]
        anchor_id = cur["id"]

        # Find first index strictly after anchor in this ordering
        start_idx = 0
        for i, o in enumerate(filtered):
            if (o.get("created_at") == anchor_created) and (o.get("id") == anchor_id):
                start_idx = i + 1
                break
        else:
            # Cursor not found in current filtered set; treat as empty page
            start_idx = len(filtered)
        page = filtered[start_idx:start_idx + limit]
        remaining = filtered[start_idx + limit:]
    else:
        page = filtered[:limit]
        remaining = filtered[limit:]

    has_more = len(remaining) > 0
    next_cursor = None
    if has_more and page:
        last = page[-1]
        if isinstance(last.get("created_at"), str) and isinstance(last.get("id"), str):
            next_cursor = _encode_cursor(last["created_at"], last["id"])

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "orders": page,
        "meta": {
            "user_id": user_id,
            "total": len(filtered),
            "returned": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms
        }
    }

def cancel_order(order_id, user_id, auth_session_id, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel_order"
    used_cred = auth_session_id

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(st)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _audit(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "credential": used_cred,
            "status": status_s,
            "error_code": (err or {}).get("code") if isinstance(err, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(_now()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if not isinstance(order_id, str) or not re.match(r"^zui_ord_[A-Za-z0-9]+$", order_id):
        e = _err("VALIDATION_ERROR", "order_id is malformed", field="order_id")
        _audit("error", e["error"])
        return e
    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[A-Za-z0-9]+$", user_id):
        e = _err("VALIDATION_ERROR", "user_id is malformed", field="user_id")
        _audit("error", e["error"])
        return e
    if not isinstance(auth_session_id, str) or not re.match(r"^zui_sess_[A-Za-z0-9]+$", auth_session_id):
        e = _err("VALIDATION_ERROR", "auth_session_id is malformed", field="auth_session_id")
        _audit("error", e["error"])
        return e

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not user:
        e = _err("NOT_FOUND", "User not found", user_id=user_id)
        _audit("error", e["error"])
        return e
    if user.get("status") != "active":
        e = _err("CONFLICT", "User is not active", user_id=user_id, status=user.get("status"))
        _audit("error", e["error"])
        return e

    sessions = _load("auth_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == auth_session_id and s.get("user_id") == user_id), None)
    if not sess:
        e = _err("UNAUTHORIZED", "auth_session_id is not valid for the given user_id", user_id=user_id, auth_session_id=auth_session_id)
        _audit("error", e["error"])
        return e

    now = _now()
    expires = _parse_dt(sess.get("access_token_expires_at"))
    if sess.get("status") != "authenticated" or not expires or expires <= now or not isinstance(sess.get("access_token"), str) or len(sess.get("access_token")) < 10:
        e = _err(
            "UNAUTHORIZED",
            "Authenticated session is required and must not be expired. Run check_and_authenticate/initiate_login to re-authenticate.",
            user_id=user_id,
            auth_session_id=auth_session_id,
            session_status=sess.get("status"),
            access_token_expires_at=sess.get("access_token_expires_at"),
        )
        _audit("error", e["error"])
        return e

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []
    idx = next((i for i, o in enumerate(orders) if isinstance(o, dict) and o.get("id") == order_id and o.get("user_id") == user_id), None)
    if idx is None:
        e = _err("NOT_FOUND", "Order not found", order_id=order_id, user_id=user_id)
        _audit("error", e["error"])
        return e

    order = orders[idx]
    if order.get("order_domain") != "kite_order":
        e = _err("CONFLICT", "Only kite_order can be cancelled with cancel_order", order_id=order_id, order_domain=order.get("order_domain"))
        _audit("error", e["error"])
        return e

    if order.get("status") in ("cancelled", "completed", "rejected"):
        e = _err("CONFLICT", "Order is not cancellable in its current status", order_id=order_id, current_status=order.get("status"))
        _audit("error", e["error"])
        return e

    # lifecycle transition check
    allowed = {
        "created": ["submitted", "failed"],
        "submitted": ["accepted", "rejected", "failed"],
        "accepted": ["completed", "cancelled", "failed"],
        "active": ["paused", "cancelled", "completed", "failed"],
        "paused": ["active", "cancelled", "failed"],
    }
    cur = order.get("status")
    if "cancelled" not in allowed.get(cur, []):
        e = _err("INVALID_TRANSITION", "Order cannot transition to cancelled from current status", order_id=order_id, from_status=cur, to_status="cancelled")
        _audit("error", e["error"])
        return e

    now_iso = _iso(now)
    upstream_resp = {
        "ok": True,
        "action": "cancel_order",
        "upstream_order_id": order.get("upstream_order_id"),
        "cancelled_at": now_iso,
    }

    order["auth_session_id"] = auth_session_id
    order["status"] = "cancelled"
    order["upstream_status"] = "CANCELLED"
    order["last_error_message"] = None
    order["response_payload"] = upstream_resp
    order["updated_at"] = now_iso
    orders[idx] = order
    _save("orders.json", orders)

    _audit("ok", meta={"order_id": order_id, "upstream_order_id": order.get("upstream_order_id")})
    return {"order": order}

def update_user_status(user_id, status, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0125000" if __import__("os").path.isdir("./environment_mix/0125000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _append_audit(endpoint, status_s, latency_ms=None, meta=None):
        audit_file = None
        for candidate in ("request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, candidate)):
                audit_file = candidate
                break
        if audit_file is None:
            return
        rows = _load(audit_file)
        if not isinstance(rows, list):
            rows = []
        now = _now()
        row = {
            "id": f"zui_req_{secrets.token_hex(8)}",
            "endpoint": endpoint,
            "status": status_s,
            "credential_id": None,
            "latency_ms": latency_ms,
            "timestamp": _iso(now),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        rows.append(row)
        _save(audit_file, rows)

    t0 = time.time()

    if not isinstance(user_id, str) or not re.match(r"^zui_usr_[A-Za-z0-9]+$", user_id):
        _append_audit("update_user_status", "error", latency_ms=int((time.time() - t0) * 1000), meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Malformed user_id.")
    if status not in ("active", "suspended", "deleted"):
        _append_audit("update_user_status", "error", latency_ms=int((time.time() - t0) * 1000), meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=["active", "suspended", "deleted"])

    users = _load("users.json")
    if not isinstance(users, list):
        _append_audit("update_user_status", "error", latency_ms=int((time.time() - t0) * 1000), meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Datastore is in an unexpected state.")

    u = next((r for r in users if isinstance(r, dict) and r.get("id") == user_id), None)
    if u is None:
        _append_audit("update_user_status", "error", latency_ms=int((time.time() - t0) * 1000), meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "User not found.", user_id=user_id)

    current = u.get("status")
    transitions = {
        "active": {"suspended", "deleted"},
        "suspended": {"active", "deleted"},
        "deleted": set(),
    }

    if status == current:
        # Idempotent update: return existing row but still update updated_at? Real systems often do not.
        _append_audit("update_user_status", "ok", latency_ms=int((time.time() - t0) * 1000), meta={"idempotent": True})
        return {"user": u, "meta": {"idempotent": True}}

    if status not in transitions.get(current, set()):
        _append_audit("update_user_status", "error", latency_ms=int((time.time() - t0) * 1000), meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Status transition not allowed.", from_status=current, to_status=status)

    # Authorization: ambient; no explicit credential param. Only refuse if no valid context exists at all.
    # With this service schema, user admin is assumed allowed for authenticated callers.
    now = _now()
    u["status"] = status
    u["updated_at"] = _iso(now)
    _save("users.json", users)

    _append_audit("update_user_status", "ok", latency_ms=int((time.time() - t0) * 1000))
    return {"user": u}

