        _append_audit("get_whoami", "error", latency_ms=int((time.time() - t0) * 1000), meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_quota must be a boolean when provided.")

    # This service schema does not include API keys/tokens collection.
    # As per contract, when signature carries no credential, caller is already authenticated.
    # Therefore, whoami returns a service identity. Only return UNAUTHORIZED if an explicit credential is required,
    # which it is not here.
    identity = {
        "service": "zerodha_integration",
        "auth_type": "ambient",
        "scopes": [
            "users:read",
            "users:write",
            "auth_sessions:read",
            "auth_sessions:write",
            "portfolio:read",
            "market_data:read",
            "orders:write",
        ],
    }

    out = {"identity": identity}

    if include_quota:
        # If an audit/request log exists, compute naive recent usage; otherwise omit.
        audit_file = None
        for candidate in ("request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, candidate)):
                audit_file = candidate
                break
        if audit_file is not None:
            rows = _load(audit_file)
            if not isinstance(rows, list):
                rows = []
            now = _now()
            # last 60 seconds usage
            cutoff = now - datetime.timedelta(seconds=60)

            def _parse_ts(v):
                if not isinstance(v, str):
                    return None
                s = v.strip()
                try:
                    if s.endswith("Z"):
                        return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                    return datetime.datetime.fromisoformat(s)
                except ValueError:
                    return None

            recent = 0
            for r in rows:
                if not isinstance(r, dict):
                    continue
                ts = _parse_ts(r.get("timestamp"))
                if ts is not None and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts is not None and ts >= cutoff:
                    recent += 1

            out["quota"] = {
                "model": "observed_only",
                "requests_last_60s": recent,
                "window_seconds": 60,
                "reset_at": _iso(now + datetime.timedelta(seconds=60)),
            }

    _append_audit("get_whoami", "ok", latency_ms=int((time.time() - t0) * 1000))
    return out
